use gba_core::{Machine,Bus};
fn call(m:&mut Machine,pc:u32,r0:u32)->u32{m.cpu=gba_core::Cpu::new();m.cpu.cpsr=0xbf;m.cpu.regs[13]=0x0203f000;m.cpu.regs[14]=0x01000001;m.cpu.regs[15]=pc;m.cpu.regs[0]=r0;for _ in 0..4000000{if m.cpu.regs[15]==0x01000000{return m.cpu.regs[0];}m.step();}panic!("timeout {:x}",m.cpu.regs[15]);}
fn extent(m:&Machine,base:usize)->[usize;4]{let mut b=[512,512,0,0];for y in 0..64{for x in 0..64{let o=base+2*(y*64+x);let t=u16::from_le_bytes(m.bus.ewram[o..o+2].try_into().unwrap());let tile=(t as usize&1023)*32;if m.bus.vram[tile..tile+32].iter().any(|b|*b!=0){b=[b[0].min(x*8),b[1].min(y*8),b[2].max(x*8+8),b[3].max(y*8+8)];}}}b}
fn main(){let r=std::fs::read(std::env::args().nth(1).unwrap()).unwrap();let mut m=Machine::new(r.clone());for(n,d)in[("ewram",&mut m.bus.ewram),("iwram",&mut m.bus.iwram),("vram",&mut m.bus.vram),("io",&mut m.bus.io)]{d.copy_from_slice(&std::fs::read(format!("target/bank-populated-{n}.bin")).unwrap());}let before=m.bus.ewram.clone();for (i,pc) in [(0usize,0x08020318),(1,0x0802045c)]{let at=0x7662a8+88*66+4+4*i;let rel=u32::from_le_bytes(r[at..at+4].try_into().unwrap());call(&mut m,pc,0x087662a8+rel);let p=call(&mut m,if i==0{0x0801be8c}else{0x0801bea8},0)as usize-0x02000000;let changes=before[p..p+8192].iter().zip(&m.bus.ewram[p..p+8192]).filter(|(a,b)|a!=b).count();for q in [0x91a0usize,0xb1a0,0xd1a0]{let n=before[q..q+8192].iter().zip(&m.bus.ewram[q..q+8192]).filter(|(a,b)|a!=b).count();println!("ALL index={i} base={q:x} changed={n} bounds={:?}",extent(&m,q));}println!("ROM_FULL_PLANE index={i} base={p:x} changed_bytes={changes} occupied_bounds={:?}",extent(&m,p));}}
